class SQLGenerator:
    def __init__(self, table_name):
        self._table_name = table_name

    @property
    def table_name(self):
        return self._table_name

    @table_name.setter
    def table_name(self, value):
        self._table_name = value

    def select(self, fields=None, condition=None):
        formatted_fields = self._format_fields(fields)
        sql = f"SELECT {formatted_fields} FROM {self.table_name}"
        if condition is not None:
            sql += f" WHERE {condition}"
        return self._terminate_sql(sql)

    def insert(self, data):
        fields = self._format_fields(list(data.keys()))
        values = self._format_values(data)
        sql = f"INSERT INTO {self.table_name} ({fields}) VALUES ({values})"
        return self._terminate_sql(sql)

    def update(self, data, condition):
        set_clause = self._format_set_clause(data)
        sql = f"UPDATE {self.table_name} SET {set_clause} WHERE {condition}"
        return self._terminate_sql(sql)

    def delete(self, condition):
        sql = f"DELETE FROM {self.table_name} WHERE {condition}"
        return self._terminate_sql(sql)

    def select_female_under_age(self, age):
        condition = self._build_female_under_age_condition(age)
        return self.select(condition=condition)

    def select_by_age_range(self, min_age, max_age):
        condition = self._build_age_range_condition(min_age, max_age)
        return self.select(condition=condition)

    def _format_fields(self, fields):
        if fields is None:
            return "*"
        return ", ".join(fields)

    def _format_values(self, data):
        return ", ".join([f"'{value}'" for value in data.values()])

    def _format_set_clause(self, data):
        return ", ".join([f"{field} = '{value}'" for field, value in data.items()])

    def _terminate_sql(self, sql):
        return sql + ";"

    def _build_female_under_age_condition(self, age):
        return f"age < {age} AND gender = 'female'"

    def _build_age_range_condition(self, min_age, max_age):
        return f"age BETWEEN {min_age} AND {max_age}"
